import { useCallback, useEffect, useState } from "react";
import {
  type DsEvent,
  type DsFixture,
  type DsRecommendation,
  type DsReview,
  type DsSnapshot,
  decisionApi,
} from "../api/decision";
import fixtureData from "../fixtures/decision.json";

// Generated by web/dev/build_decision_fixtures.py from the real decision engine.
const FIXTURE = fixtureData as unknown as DsFixture;

export type DsSource = "probing" | "api" | "fixture";

export interface DsDoc {
  /** Identifier cited by every figure (data-src). */
  id: string;
  reco: DsRecommendation;
  /** SHA-256 of the full engine output when the bundled copy is compacted. */
  sourceSha?: string;
}

export interface DecisionStore {
  source: DsSource;
  units: Array<{ id: string; name: string }>;
  unit: string;
  setUnit: (id: string) => void;
  snapshot: DsSnapshot | null;
  auto: DsDoc | null;
  manual: DsDoc | null;
  manualExamples: DsFixture["manual"];
  events: DsEvent[];
  error: string | null;
  reload: () => void;
  simulate: (locks: unknown) => Promise<void>;
  showExample: (id: string) => void;
  review: (doc: DsDoc, decision: "approve" | "reject") => Promise<DsReview>;
  inject: (event: string) => Promise<void>;
}

const fixtureUnits = FIXTURE.units.map(({ id, name }) => ({ id, name }));

/** Offline: the decision proposed by the engine is still a computed one (bundled outputs). */
function fixtureReview(doc: DsDoc, decision: "approve" | "reject"): DsReview {
  if (decision === "reject") {
    return { outcome: "REJECTED", reasons: [], recompute_required: false, external_command_sent: false, replayed: false };
  }
  return doc.reco.approvable
    ? { outcome: "APPROVED_IN_DEMO", reasons: [], recompute_required: false, external_command_sent: false }
    : {
        outcome: "REFUSED",
        reasons: [`not_approvable:${doc.reco.status}`],
        recompute_required: false,
        external_command_sent: false,
        replayed: false,
      };
}

export function useDecision(): DecisionStore {
  const [source, setSource] = useState<DsSource>("probing");
  const [units, setUnits] = useState(fixtureUnits);
  const [unit, setUnit] = useState(fixtureUnits[0]?.id ?? "nominal_auto");
  const [snapshot, setSnapshot] = useState<DsSnapshot | null>(null);
  const [auto, setAuto] = useState<DsDoc | null>(null);
  const [manual, setManual] = useState<DsDoc | null>(null);
  const [events, setEvents] = useState<DsEvent[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [nonce, setNonce] = useState(0);

  // Detect the source once: local engine API, else bundled engine outputs.
  useEffect(() => {
    let alive = true;
    decisionApi
      .units()
      .then((r) => {
        if (!alive) return;
        setUnits(r.units);
        setEvents(r.events);
        setSource("api");
      })
      .catch(() => {
        if (!alive) return;
        setEvents(FIXTURE.events);
        setSource("fixture");
      });
    return () => {
      alive = false;
    };
  }, []);

  // The automatic recommendation is computed on arrival, without any input from the person.
  useEffect(() => {
    if (source === "probing") return;
    let alive = true;
    setManual(null);
    setError(null);
    if (source === "fixture") {
      const u = FIXTURE.units.find((x) => x.id === unit) ?? FIXTURE.units[0];
      if (u) {
        setSnapshot(u.snapshot);
        setAuto({ id: u.recommendation.recommendation_id, reco: u.recommendation, sourceSha: u.source_sha256 });
      }
      return;
    }
    setAuto(null);
    decisionApi
      .auto(unit)
      .then((r) => {
        if (!alive) return;
        setSnapshot(r.snapshot);
        setAuto({ id: r.doc_id, reco: r.recommendation });
      })
      .catch((e: unknown) => alive && setError(String(e)));
    return () => {
      alive = false;
    };
  }, [source, unit, nonce]);

  const reload = useCallback(() => setNonce((n) => n + 1), []);

  const simulate = useCallback(
    async (locks: unknown) => {
      if (source !== "api") throw new Error("La simulation libre demande l'API locale du moteur.");
      const r = await decisionApi.simulate(unit, locks);
      setManual({ id: r.doc_id, reco: r.recommendation });
    },
    [source, unit],
  );

  const showExample = useCallback((id: string) => {
    const ex = FIXTURE.manual.find((m) => m.id === id);
    if (ex) setManual({ id: ex.recommendation.recommendation_id, reco: ex.recommendation, sourceSha: ex.source_sha256 });
  }, []);

  const review = useCallback(
    async (doc: DsDoc, decision: "approve" | "reject") => {
      if (source !== "api") return fixtureReview(doc, decision);
      const r = await decisionApi.review(unit, doc.reco.recommendation_id, decision, `${doc.id}:${decision}`);
      return r.review;
    },
    [source, unit],
  );

  const inject = useCallback(
    async (event: string) => {
      if (source === "api") await decisionApi.inject(unit, event);
    },
    [source, unit],
  );

  return {
    source,
    units,
    unit,
    setUnit,
    snapshot,
    auto,
    manual,
    manualExamples: FIXTURE.manual,
    events: events.filter((e) => e.unit === unit),
    error,
    reload,
    simulate,
    showExample,
    review,
    inject,
  };
}
